tariff "t"
var total = $0
for x in [1, 2, 3] {
  total += $10 * x
}
note "{total}"

tariff "t"
if true {
  var y = 1
  y += 1
  note "{y}"
}

tariff "t"
if 1 < 2 {
  note "yes"
} else {
  note "no"
}

tariff "t"
if 1 > 2 {
  note "yes"
} else {
  note "no"
}

tariff "t"
let w = 1_500 lb
if w < 500 lb {
  note "light"
} else if w < 2_000 lb {
  note "medium"
} else {
  note "heavy"
}

tariff "t"
if false {
  note "x"
}
note "done"

tariff "t"
if let p = shipment.pickup {
  note "{p.sequence}"
}

tariff "t"
if let w = shipment.weight {
  note "{w}"
} else {
  note "no weight"
}

tariff "t"
for x in ["a", "b"] {
  note "{x}"
}

tariff "t"
for i in 1..4 {
  note "{i}"
}

tariff "t"
for i in 1..=2 {
  note "{i}"
}

tariff "t"
for i in 3..3 {
  note "{i}"
}
note "end"

tariff "t"
for i in 1..=6 where i % 2 == 0 {
  note "{i}"
}

tariff "t"
for i in 1..10 {
  if i == 3 {
    break
  }
  note "{i}"
}

tariff "t"
for i in 1..=4 {
  if i == 2 {
    continue
  }
  note "{i}"
}

tariff "t"
for i in 1..=2 {
  for j in 1..=5 {
    if j > 1 {
      break
    }
    note "{i}.{j}"
  }
}

tariff "t"
for s in shipment.stops {
  if s.kind == Delivery {
    fail "stop {s.sequence}"
  }
}

tariff "t"
fn twice(x: Int) -> Int {
  return x * 2
}
note "{twice(4)}"

tariff "t"
fn deadhead(empty: Distance, rate: Money/mi) -> Money {
  let paid = (empty - 50 mi).max(0 mi)
  return rate * paid
}
note "{deadhead(rate: $2/mi, empty: 80 mi)}"

tariff "t"
fn sign(x: Int) -> Text {
  if x < 0 {
    return "negative"
  }
  return "positive"
}
note "{sign(-1)} {sign(1)}"

tariff "t"
fn firstBig(xs: List<Int>) -> Int {
  for x in xs {
    if x > 10 {
      return x
    }
  }
  return 0
}
note "{firstBig([1, 20, 30])}"

tariff "t"
fn need(x: Int?) -> Int {
  require let v = x else "missing"
  return v
}
let y = need(none)

tariff "t"
use std.accessorials.{ detention }
let owed = detention(5 h, rate: $60/h, increment: 0 min)

tariff "t"
enum Zone { A, B }
let z = Zone.B
if z == B {
  note "b"
}

tariff "t"
type Fee = { code: Text, amount: Money }
let f: Fee = { code: "X", amount: $5 }
note "{f.code} {f.amount}"
